mitigation.zh:
跳转前先解析 URL 取 authority，与预注册域名白名单精确比对；仅允许站内相对路径或白名单目标，拒绝 userinfo 伪装与协议相对 URL。
    # Python/Flask：解析后比对 host，拒绝站外目标
    from urllib.parse import urlparse
    from flask import redirect, url_for
    ALLOWED = {'example.com'}
    u = urlparse(next_url or '')
    if u.netloc and u.netloc not in ALLOWED:
        next_url = url_for('index')      # 回退首页
    return redirect(next_url)
